//! R10 closure: live Binance Futures partial depth20 + OKX books5, public data only.
use futures_util::{SinkExt,StreamExt};use serde_json::{json,Value};use std::{collections::{HashMap,HashSet},time::{Duration,Instant,SystemTime,UNIX_EPOCH}};use tokio_tungstenite::{connect_async,tungstenite::Message};
fn wall()->i64{SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_millis()as i64}
fn lv(v:&Value)->Option<Vec<(f64,f64)>>{Some(v.as_array()?.iter().filter_map(|x|{let a=x.as_array()?;Some((a.get(0)?.as_str()?.parse().ok()?,a.get(1)?.as_str()?.parse().ok()?))}).collect())}
#[tokio::main]async fn main(){let bases=std::env::var("R10_BASES").unwrap().split(',').map(str::to_string).collect::<Vec<_>>();let secs=std::env::var("R10_SECONDS").ok().and_then(|x|x.parse().ok()).unwrap_or(60);let start=Instant::now();let mut bb:HashMap<String,(Vec<(f64,f64)>,Vec<(f64,f64)>,u64,i64)>=HashMap::new();let mut ob:HashMap<String,(Vec<(f64,f64)>,Vec<(f64,f64)>,u64,i64)>=HashMap::new();let(mut bs,mut os)=(HashSet::new(),HashSet::new());let(mut errors,mut updates)=(0u64,0u64);let streams=bases.iter().map(|x|format!("{}usdt@depth20@100ms",x.to_lowercase())).collect::<Vec<_>>().join("/");let(mut b,_)=connect_async(format!("wss://fstream.binance.com/stream?streams={streams}")).await.unwrap();let(mut o,_)=connect_async("wss://ws.okx.com:8443/ws/v5/public").await.unwrap();let args=bases.iter().map(|x|json!({"channel":"books5","instId":format!("{x}-USDT")})).collect::<Vec<_>>();o.send(Message::Text(json!({"op":"subscribe","args":args}).to_string())).await.unwrap();while start.elapsed()<Duration::from_secs(secs){tokio::select!{x=b.next()=>if let Some(Ok(Message::Text(raw)))=x{updates+=1;let now=start.elapsed().as_nanos()as u64;match serde_json::from_str::<Value>(&raw){Ok(v)=>{let d=&v["data"];let sym=d["s"].as_str().unwrap_or("").strip_suffix("USDT").unwrap_or("").to_string();if sym.is_empty(){errors+=1;continue}match(lv(&d["b"]),lv(&d["a"])){(Some(bd),Some(ak))if!bd.is_empty()&&!ak.is_empty()=>{bs.insert(sym.clone());bb.insert(sym,(bd,ak,now,wall()));},_=>errors+=1}},Err(_)=>errors+=1}},x=o.next()=>if let Some(Ok(Message::Text(raw)))=x{if raw.contains("\"event\""){continue}updates+=1;let now=start.elapsed().as_nanos()as u64;match serde_json::from_str::<Value>(&raw){Ok(v)=>{let id=v["arg"]["instId"].as_str().unwrap_or("");let sym=id.strip_suffix("-USDT").unwrap_or("").to_string();let row=v["data"].as_array().and_then(|a|a.first());if let Some(r)=row{match(lv(&r["bids"]),lv(&r["asks"])){(Some(bd),Some(ak))if!bd.is_empty()&&!ak.is_empty()=>{os.insert(sym.clone());ob.insert(sym,(bd,ak,now,wall()));},_=>errors+=1}}},Err(_)=>errors+=1}}}}let now=start.elapsed().as_nanos()as u64;let mut paired=0;let(mut fresh,mut blevels,mut olevels)=(0,0usize,0usize);for x in &bases{if let(Some(b),Some(o))=(bb.get(x),ob.get(x)){paired+=1;blevels=blevels.max(b.0.len().max(b.1.len()));olevels=olevels.max(o.0.len().max(o.1.len()));if now>=b.2&&now-b.2<=800_000_000&&now>=o.2&&now-o.2<=800_000_000{fresh+=1}}}println!("{}",json!({"r10_binance_depth_live":errors==0&&paired==bases.len(),"requested":bases.len(),"binance_seen":bs.len(),"okx_seen":os.len(),"paired":paired,"fresh_final":fresh,"binance_max_levels":blevels,"okx_max_levels":olevels,"updates":updates,"errors":errors,"binance_stream":"depth20@100ms","okx_stream":"books5","trading":false}));}